                routes.pop(i)
                if j > i:
                    j -= 1
            routes[j] = improve_2opt(routes[j])
            if i < len(routes):
                routes[i] = improve_2opt(routes[i])
            changed = True
            continue

        # swap between routes if helpful
        best_swap = None
        best_delta = 0
        for i in range(len(routes)):
            ri = routes[i]
            li = load_of(ri)
            for p, a in enumerate(ri):
                da = demand(a)
                la = li - da
                aL = depot if p == 0 else ri[p - 1]
                aR = depot if p == len(ri) - 1 else ri[p + 1]
                rem_a = d(aL, a) + d(a, aR) - d(aL, aR)
                for j in range(i + 1, len(routes)):
                    rj = routes[j]
                    lj = load_of(rj)
                    for q, b in enumerate(rj):
                        db = demand(b)
                        if la + db > capacity or lj - db + da > capacity:
                            continue
                        bL = depot if q == 0 else rj[q - 1]
                        bR = depot if q == len(rj) - 1 else rj[q + 1]
                        rem_b = d(bL, b) + d(b, bR) - d(bL, bR)
                        ins_a = d(bL, a) + d(a, bR) - d(bL, bR)
                        ins_b = d(aL, b) + d(b, aR) - d(aL, aR)
                        delta = (ins_a + ins_b) - (rem_a + rem_b)
                        if delta < best_delta - 1e-12 or (delta == best_delta and best_swap is not None and (i, p, j, q, a, b) < best_swap):
                            best_delta = delta
                            best_swap = (i, p, j, q, a, b)
        if best_swap is not None and best_delta < -1e-12:
            i, p, j, q, a, b = best_swap
            routes[i][p], routes[j][q] = b, a
            routes[i] = improve_2opt(routes[i])
            routes[j] = improve_2opt(routes[j])
            changed = True

    # Final cleanup: remove empties, deterministic order by first customer
    routes = [rt for rt in routes if rt]
    routes.sort(key=lambda rt: (rt[0], len(rt), rt))
    return routes
